#include <linux/drm/i915_drv.h>

int parse_iomm(struct drm_device *drm_dev, const char *reg_name, u32 *io_addr) {
	int ret = 0;
	const char *p = reg_name;
	const char *plast;
	int len;
	u32 val;

	/* we only support IOMMU variants of the register names right now.
	 * so we expect something like "IOMMU_<REG>"
	 */
	if (strncmp(p, "IOMMU_", 6)) {
		DRM_ERROR("unexpected register name %s\n", reg_name);
		return -EINVAL;
	}
	p += 6;

	len = strlen(p);

	plast = strchr(p, ' ');
	if (plast) {
		len = plast - p;
		if (len == 0) {
			DRM_ERROR("malformed register name %s\n", reg_name);
			return -EINVAL;
		}
	}

	if (len > 4) {
		DRM_ERROR("unexpected register name %s\n", reg_name);
		return -EINVAL;
	}

	val = 0;
	while (len--) {
		unsigned char c = *p++;
		val = (val << 4) | (c - '0');
	}

	*io_addr = IOMMU_BASE + val;
	return ret;
}
```

